// It overwrites the guide-first-visit page, so it runs only where tests/setup/e2eUsers.ts runs: a
// database whose name or file name contains "e2e".
function databaseName(url = ''): string {
  try {
    const parsed = new URL(url);
    return parsed.protocol === 'file:' ? path.basename(url.slice('file:'.length)) : parsed.pathname;
  } catch {
    return '';
  }
}
const env = readEnv();
if (
  !/e2e/i.test(databaseName(process.env.DATABASE_URL)) ||
  env.nodeEnv === 'production' ||
  env.allowIndexing
) {
  throw new Error(
    'qa-fixture: refused. It writes sample people and overwrites the first-visit guide, so it runs only on an e2e database (DATABASE_URL naming e.g. .data/e2e.db or sefid_e2e) outside production; use npm run db:e2e.',
  );
}

const payload = await getPayload({ config });
const context = SEED_CONTEXT;

async function first<T>(find: Promise<{ docs: T[] }>): Promise<T | undefined> {
  return (await find).docs[0];
}

/** A media document from generated bytes, matched by `seedSource`. */
async function media(source: string, alt: string, file: () => Promise<Buffer>, mimetype: string) {
  const found = await first(
    payload.find({
      collection: 'media',
      where: { seedSource: { equals: source } },
      limit: 1,
      depth: 0,
    }),
  );
  if (found) return found.id;
  const data = await file();
  const doc = await payload.create({
    collection: 'media',
    data: { alt, seedSource: source },
    file: { data, name: path.basename(source), mimetype, size: data.length },
    context,
  });
  return doc.id;
}

