/** Create, or bring an earlier fixture document back to this content (and published). */
async function upsert<C extends 'doctors' | 'cases' | 'testimonials'>(
  collection: C,
  where: Where,
  data: Record<string, unknown>,
) {
  const found = await first(payload.find({ collection, where, limit: 1, depth: 0 }));
  const values = { ...data, _status: 'published' } as never;
  const doc = found
    ? await payload.update({ collection, id: found.id, data: values, context })
    : await payload.create({ collection, data: values, context });
  return doc as { id: number; slug?: string };
}

